import json,re
MARKER_RE = re.compile(r"ch:trace\s+row=[^\"'`]*", re.IGNORECASE)
FIELD_RE = re.compile(r"\b(row|spec|wave|test|doc|prompt|evidence|witness|verdict|commit|memory)=([^\s\"'`,;]+)")
with open('.coding-hermes/board/tasks.jsonl',encoding='utf-8',errors='replace') as fh:
    for i,line in enumerate(fh,1):
        if 'ch:trace' not in line: continue
        try: r=json.loads(line)
        except Exception: continue
        for k,v in r.items():
            if not isinstance(v,str): continue
            for m in MARKER_RE.finditer(v):
                f=dict(FIELD_RE.findall(m.group(0)))
                c=f.get('commit','')
                if c and not c.startswith('none:') and not re.match(r'^[0-9a-f]{7,64}$',c,re.I):
                    print("NON-HEX commit",i,r.get('id'),r.get('status'),k,c)
                if c and re.match(r'^[0-9a-f]{7,64}$',c,re.I):
                    print("HEX commit",i,r.get('id'),r.get('status'),k,c)
EOF

